{"command":"cat <<'EOF' > gen_std_calls.go
package main

import (
	"bytes"
	"fmt"
	"go/types"
	"golang.org/x/tools/go/packages"
	"os"
	"strings"
)

func main() {
	cfg := &packages.Config{
		Mode: packages.NeedName | packages.NeedTypes | packages.NeedImports | packages.NeedDeps | packages.NeedExportsFile,
	}
	pkgs, err := packages.Load(cfg, "std")
	if err != nil {
		fmt.Fprintf(os.Stderr, "load: %v\n", err)
		os.Exit(1)
	}

	var funcs []string
	var imports []string

	visited := make(map[string]bool)

	for _, pkg := range pkgs {
		if pkg.PkgPath == "unsafe" {
			continue
		}
		scope := pkg.Types.Scope()
		for _, name := range scope.Names() {
			obj := scope.Lookup(name)

			// Check functions
			if fn, ok := obj.(*types.Func); ok {
				if sig, ok := fn.Type().(*types.Signature); ok {
					if returnsError(sig) {
						funcs = append(funcs, fmt.Sprintf("%s.%s()", pkg.Types.Name(), fn.Name()))
						visited[pkg.Types.Path()] = true
					}
				}
			}

			// Check methods on named types
			if tname, ok := obj.(*types.TypeName); ok {
				if named, ok := tname.Type().(*types.Named); ok {
					for i := 0; i < named.NumMethods(); i++ {
						m := named.Method(i)
						if sig, ok := m.Type().(*types.Signature); ok {
							if returnsError(sig) {
								funcs = append(funcs, fmt.Sprintf("var _%d %s.%s\n_%d.%s()", len(funcs), pkg.Types.Name(), tname.Name(), len(funcs), m.Name()))
								visited[pkg.Types.Path()] = true
							}
						}
					}
					// check pointer methods
					if ptr, ok := types.NewPointer(named).(*types.Pointer); ok {
						mset := types.NewMethodSet(ptr)
						for i := 0; i < mset.Len(); i++ {
							m := mset.At(i).Obj()
							// only add if not already in named (to avoid duplicates, though it's fine)
							if sig, ok := m.Type().(*types.Signature); ok {
								if returnsError(sig) {
									funcs = append(funcs, fmt.Sprintf("var _p%d *%s.%s\n_p%d.%s()", len(funcs), pkg.Types.Name(), tname.Name(), len(funcs), m.Name()))
									visited[pkg.Types.Path()] = true
								}
							}
						}
					}
				}
			}
		}
	}

	for p := range visited {
		imports = append(imports, fmt.Sprintf(`"%s"`, p))
	}

	out := &bytes.Buffer{}
	out.WriteString("package stdcalls\n\nimport (\n")
	for _, imp := range imports {
		out.WriteString(imp + "\n")
	}
	out.WriteString(")\n\nfunc CallAll() {\n")
	for _, f := range funcs {
		out.WriteString(f + "\n")
	}
	out.WriteString("}\n")

	os.WriteFile("stdcalls/stdcalls.go", out.Bytes(), 0644)
}

func returnsError(sig *types.Signature) bool {
	res := sig.Results()
	if res == nil {
		return false
	}
	for i := 0; i < res.Len(); i++ {
		if res.At(i).Type().String() == "error" {
			return true
		}
	}
	return false
}
EOF
go mod init gen
go get golang.org/x/tools/go/packages
go run gen_std_calls.go
mkdir -p stdcalls
go run gen_std_calls.go
"}

