package main

import (
	"bytes"
	"fmt"
	"go/importer"
	"go/types"
	"os"
	"os/exec"
	"strings"
)

func main() {
	cmd := exec.Command("go", "list", "std")
	out, err := cmd.Output()
	if err != nil {
		panic(err)
	}

	pkgs := strings.Split(strings.TrimSpace(string(out)), "\n")
	imp := importer.Default()

	var funcs []string
	var imports []string
	visited := make(map[string]bool)

	for _, pkgName := range pkgs {
		if strings.Contains(pkgName, "vendor/") || strings.Contains(pkgName, "internal/") {
			continue
		}
		if pkgName == "unsafe" {
			continue
		}
		pkg, err := imp.Import(pkgName)
		if err != nil {
			continue
		}
		scope := pkg.Scope()
		for _, name := range scope.Names() {
			obj := scope.Lookup(name)
			if fn, ok := obj.(*types.Func); ok {
				if sig, ok := fn.Type().(*types.Signature); ok {
					if returnsError(sig) {
						funcs = append(funcs, generateCall(pkg.Name(), fn.Name(), sig, "", false))
						visited[pkg.Path()] = true
					}
				}
			}
			if tname, ok := obj.(*types.TypeName); ok {
				if named, ok := tname.Type().(*types.Named); ok {
					for i := 0; i < named.NumMethods(); i++ {
						m := named.Method(i)
						if sig, ok := m.Type().(*types.Signature); ok {
							if returnsError(sig) {
								funcs = append(funcs, generateCall(pkg.Name(), m.Name(), sig, tname.Name(), false))
								visited[pkg.Path()] = true
							}
						}
					}
					if ptr, ok := types.NewPointer(named).(*types.Pointer); ok {
						mset := types.NewMethodSet(ptr)
						for i := 0; i < mset.Len(); i++ {
							m := mset.At(i).Obj()
							if sig, ok := m.Type().(*types.Signature); ok {
								if returnsError(sig) {
									funcs = append(funcs, generateCall(pkg.Name(), m.Name(), sig, tname.Name(), true))
									visited[pkg.Path()] = true
								}
							}
						}
					}
				}
			}
		}
	}

	for p := range visited {
		imports = append(imports, fmt.Sprintf(`"%s"`, p))
	}

	buf := &bytes.Buffer{}
	buf.WriteString("package stdcalls\n\nimport (\n")
	for _, i := range imports {
		buf.WriteString(i + "\n")
	}
	buf.WriteString(")\n\nfunc CallAll() {\n")
	for _, f := range funcs {
		buf.WriteString(f + "\n")
	}
	buf.WriteString("}\n")

	os.Mkdir("stdcalls", 0755)
	os.WriteFile("stdcalls/stdcalls.go", buf.Bytes(), 0644)
	os.WriteFile("stdcalls/go.mod", []byte("module stdcalls\ngo 1.22\n"), 0644)
}

func returnsError(sig *types.Signature) bool {
	res := sig.Results()
	if res == nil {
		return false
	}
	for i := 0; i < res.Len(); i++ {
		if res.At(i).Type().String() == "error" {
			return true
		}
	}
	return false
}

func generateCall(pkg, name string, sig *types.Signature, typeName string, isPtr bool) string {
	args := []string{}
	for i := 0; i < sig.Params().Len(); i++ {
		p := sig.Params().At(i)
		args = append(args, zeroValue(p.Type()))
	}
	argStr := strings.Join(args, ", ")

	if typeName == "" {
		return fmt.Sprintf("%s.%s(%s)", pkg, name, argStr)
	}

	if isPtr {
		return fmt.Sprintf("(*%s.%s)(nil).%s(%s)", pkg, typeName, name, argStr)
	}
	return fmt.Sprintf("var _v %s.%s\n_v.%s(%s)", pkg, typeName, name, argStr)
}

func zeroValue(t types.Type) string {
	switch t := t.(type) {
	case *types.Basic:
		switch t.Kind() {
		case types.Bool: return "false"
		case types.Int, types.Int8, types.Int16, types.Int32, types.Int64: return "0"
		case types.Uint, types.Uint8, types.Uint16, types.Uint32, types.Uint64: return "0"
		case types.Float32, types.Float64: return "0.0"
		case types.String: return `""`
		default: return "nil" // for untyped nil, etc
		}
	default:
		return "nil"
	}
}
EOF
go run gen_std_calls.go
