						m := mset.At(i).Obj()
						if !types.IsExported(m.Name()) { continue }
						if sig, ok := m.Type().(*types.Signature); ok {
							if returnsError(sig) {
								id := fmt.Sprintf("%s.%s.%s", pkg.Name(), tname.Name(), m.Name())
								if !uniqueFuncs[id] {
									uniqueFuncs[id] = true
									funcs = append(funcs, generateCall(alias, m.Name(), sig, tname.Name(), false))
									used = true
								}
							}
						}
					}

					ptr := types.NewPointer(named)
					msetPtr := types.NewMethodSet(ptr)
					for i := 0; i < msetPtr.Len(); i++ {
						m := msetPtr.At(i).Obj()
						if !types.IsExported(m.Name()) { continue }
						if sig, ok := m.Type().(*types.Signature); ok {
							if returnsError(sig) {
								id := fmt.Sprintf("*%s.%s.%s", pkg.Name(), tname.Name(), m.Name())
								if !uniqueFuncs[id] {
									uniqueFuncs[id] = true
									funcs = append(funcs, generateCall(alias, m.Name(), sig, tname.Name(), true))
									used = true
								}
							}
						}
					}
				}
			}
		}
		if used {
			visited[pkg.Path()] = alias
		}
	}

	for p, alias := range visited {
		imports = append(imports, fmt.Sprintf(`%s "%s"`, alias, p))
	}

	buf := &bytes.Buffer{}
	buf.WriteString("package stdcalls\n\nimport (\n")
	for _, i := range imports {
		buf.WriteString(i + "\n")
	}
	buf.WriteString(")\n\nfunc CallAll() {\n")
	for _, f := range funcs {
		buf.WriteString(f + "\n")
	}
	buf.WriteString("}\n")

