	ignoreRegexes := make(map[string]*regexp.Regexp)
	if ignore != "" {
		for _, pair := range strings.Split(ignore, ",") {
			parts := strings.SplitN(pair, ":", 2)
			if len(parts) == 2 {
				if r, err := regexp.Compile(parts[1]); err == nil {
					ignoreRegexes[parts[0]] = r
				}
			}
		}
	}
	if ignorepkg != "" {
		for _, p := range strings.Split(ignorepkg, ",") {
			ignoreRegexes[p] = regexp.MustCompile(".*")
		}
	}

	cfg := &packages.Config{
		Mode:  packages.NeedName | packages.NeedFiles | packages.NeedCompiledGoFiles | packages.NeedImports | packages.NeedDeps | packages.NeedTypes | packages.NeedTypesInfo | packages.NeedSyntax | packages.NeedModule,
		Tests: !ignoretests,
	}
	if mod != "" {
		cfg.BuildFlags = append(cfg.BuildFlags, "-mod="+mod)
	}
	if len(tags) > 0 {
		cfg.BuildFlags = append(cfg.BuildFlags, "-tags="+strings.Join(tags, ","))
	}

	pkgs, err := packages.Load(cfg, args...)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: failed to check packages: %v\n", err)
		os.Exit(2)
	}

	var hasLoadErrors bool
	var loadErrorMsgs []string
	for _, pkg := range pkgs {
		if len(pkg.Errors) > 0 {
			hasLoadErrors = true
			var msgs []string
			for _, e := range pkg.Errors {
				msgs = append(msgs, e.Msg)
			}
			loadErrorMsgs = append(loadErrorMsgs, fmt.Sprintf("%s: [-%s]", pkg.ID, strings.Join(msgs, "\n")))
		}
	}
	if hasLoadErrors {
		fmt.Fprintf(os.Stderr, "error: failed to check packages: errors while loading package %s\n", strings.Join(loadErrorMsgs, " "))
		os.Exit(2)
	}

	var errorsFound []UncheckedError

	for _, pkg := range pkgs {
		if verbose {
			fmt.Fprintf(os.Stderr, "checking %s\n", pkg.ID)
		}
		for _, f := range pkg.Syntax {
			pos := pkg.Fset.Position(f.Pos())
			if ignoretests && strings.HasSuffix(pos.Filename, "_test.go") {
				continue
			}
			if ignoregenerated {
				var isGen bool
				for _, cg := range f.Comments {
					for _, c := range cg.List {
						if strings.HasPrefix(c.Text, "// Code generated") && strings.HasSuffix(c.Text, " DO NOT EDIT.") {
							isGen = true
						}
					}
				}
				if isGen {
					continue
				}
			}

			ast.Inspect(f, func(n ast.Node) bool {
				switch node := n.(type) {
				case *ast.ExprStmt:
					if call, ok := node.X.(*ast.CallExpr); ok && returnsError(pkg, call) {
						processError(pkg, call, call.Lparen, node)
					} else if ta, ok := node.X.(*ast.TypeAssertExpr); ok && asserts {
						processTypeAssert(pkg, ta, ta.Pos(), node)
					}
				case *ast.GoStmt:
					if call, ok := node.Call.(*ast.CallExpr); ok && returnsError(pkg, call) {
						processError(pkg, call, call.Lparen, node)
					}
				case *ast.DeferStmt:
					if call, ok := node.Call.(*ast.CallExpr); ok && returnsError(pkg, call) {
						processError(pkg, call, call.Lparen, node)
					}
				case *ast.AssignStmt:
					if blank {
						if len(node.Lhs) == len(node.Rhs) {
							for i, rhs := range node.Rhs {
								if call, ok := rhs.(*ast.CallExpr); ok && returnsError(pkg, call) {
									if isBlank(node.Lhs[i]) {
										processError(pkg, call, node.Lhs[i].Pos(), node)
									}
								} else if ta, ok := rhs.(*ast.TypeAssertExpr); ok && asserts {
									if isBlank(node.Lhs[i]) {
										processTypeAssert(pkg, ta, node.Lhs[i].Pos(), node)
									}
								}
							}
						} else if len(node.Rhs) == 1 {
							if call, ok := node.Rhs[0].(*ast.CallExpr); ok && returnsError(pkg, call) {
								if isBlank(node.Lhs[len(node.Lhs)-1]) {
									processError(pkg, call, node.Lhs[len(node.Lhs)-1].Pos(), node)
								}
							} else if ta, ok := node.Rhs[0].(*ast.TypeAssertExpr); ok && asserts {
								if len(node.Lhs) == 2 && isBlank(node.Lhs[1]) {
									processTypeAssert(pkg, ta, node.Lhs[1].Pos(), node)
								}
							}
						}
					}
					if asserts {
						if len(node.Rhs) == 1 && len(node.Lhs) == 1 {
							if ta, ok := node.Rhs[0].(*ast.TypeAssertExpr); ok {
								processTypeAssert(pkg, ta, ta.Pos(), node)
							}
						}
					}
				case *ast.ValueSpec:
					if blank {
						if len(node.Values) == 1 {
							if call, ok := node.Values[0].(*ast.CallExpr); ok && returnsError(pkg, call) {
								if len(node.Names) > 0 && isBlank(node.Names[len(node.Names)-1]) {
									processError(pkg, call, node.Names[len(node.Names)-1].Pos(), node)
								}
							}
						} else if len(node.Values) > 1 {
							for i, v := range node.Values {
								if call, ok := v.(*ast.CallExpr); ok && returnsError(pkg, call) {
									if i < len(node.Names) && isBlank(node.Names[i]) {
										processError(pkg, call, node.Names[i].Pos(), node)
									}
								}
							}
						}
					}
				}
				return true
			})
		}
	}

	processErrorFunc := func(pkg *packages.Package, call *ast.CallExpr, reportPos token.Pos, node ast.Node) {
		funcName := getFuncName(pkg, call)
		if funcName != "" {
			parts := strings.Split(funcName, ".")
			pkgPath := ""
			name := ""
			if strings.HasPrefix(funcName, "(") || strings.HasPrefix(funcName, "(*") {
				// method
				idx := strings.Index(funcName, ")")
				pkgPath = funcName[:idx]
				pkgPath = strings.TrimPrefix(pkgPath, "(*")
				pkgPath = strings.TrimPrefix(pkgPath, "(")
				if dot := strings.LastIndex(pkgPath, "."); dot != -1 {
					pkgPath = pkgPath[:dot]
				}
				name = funcName[idx+2:]
			} else {
				if len(parts) > 1 {
					pkgPath = strings.Join(parts[:len(parts)-1], ".")
					name = parts[len(parts)-1]
				} else {
					name = parts[0]
				}
			}
			if r, ok := ignoreRegexes[pkgPath]; ok && r.MatchString(name) {
				return
			}
			if r, ok := ignoreRegexes[""]; ok && r.MatchString(name) {
				return
			}

			normFuncName := normalize(funcName)
			argType := getFirstArgType(pkg, call)
			excluded := false
			for _, e := range excludes {
				if e.Name == normFuncName || e.Name == normalize(name) {
					if e.Type == "" || e.Type == argType {
						excluded = true
						break
					}
				}
			}
			if excluded {
				return
			}
		}

		var buf bytes.Buffer
		printer.Fprint(&buf, pkg.Fset, node)
		line := buf.String()

		pos := pkg.Fset.Position(reportPos)
		if abspath {
			abs, err := filepath.Abs(pos.Filename)
			if err == nil {
				pos.Filename = abs
			}
		}

		errorsFound = append(errorsFound, UncheckedError{
			Pos:      pos,
			Line:     line,
			FuncName: funcName,
		})
	}

	processTypeAssertFunc := func(pkg *packages.Package, ta *ast.TypeAssertExpr, reportPos token.Pos, node ast.Node) {
		var buf bytes.Buffer
		printer.Fprint(&buf, pkg.Fset, node)
		line := buf.String()

		pos := pkg.Fset.Position(reportPos)
		if abspath {
			abs, err := filepath.Abs(pos.Filename)
			if err == nil {
				pos.Filename = abs
			}
		}

		errorsFound = append(errorsFound, UncheckedError{
			Pos:      pos,
			Line:     line,
			FuncName: "",
		})
	}

	// This is a quick hack to pass the functions down to the ast.Inspect
	// since they use errorsFound which is local.
	// In the ast.Inspect we just replace processError with processErrorFunc.
	// For simplicity, we just rebuild the AST inspection here to capture closures properly.

	errorsFound = nil
	for _, pkg := range pkgs {
		for _, f := range pkg.Syntax {
			pos := pkg.Fset.Position(f.Pos())
			if ignoretests && strings.HasSuffix(pos.Filename, "_test.go") {
				continue
			}
			if ignoregenerated {
				var isGen bool
				for _, cg := range f.Comments {
					for _, c := range cg.List {
						if strings.HasPrefix(c.Text, "// Code generated") && strings.HasSuffix(c.Text, " DO NOT EDIT.") {
							isGen = true
						}
					}
				}
				if isGen {
					continue
				}
			}

			ast.Inspect(f, func(n ast.Node) bool {
				switch node := n.(type) {
				case *ast.ExprStmt:
					if call, ok := node.X.(*ast.CallExpr); ok && returnsError(pkg, call) {
						processErrorFunc(pkg, call, call.Lparen, node)
					} else if ta, ok := node.X.(*ast.TypeAssertExpr); ok && asserts {
						processTypeAssertFunc(pkg, ta, ta.Pos(), node)
					}
				case *ast.GoStmt:
					if call, ok := node.Call.(*ast.CallExpr); ok && returnsError(pkg, call) {
						processErrorFunc(pkg, call, call.Lparen, node)
					}
				case *ast.DeferStmt:
					if call, ok := node.Call.(*ast.CallExpr); ok && returnsError(pkg, call) {
						processErrorFunc(pkg, call, call.Lparen, node)
					}
				case *ast.AssignStmt:
					if blank {
						if len(node.Lhs) == len(node.Rhs) {
							for i, rhs := range node.Rhs {
								if call, ok := rhs.(*ast.CallExpr); ok && returnsError(pkg, call) {
									if isBlank(node.Lhs[i]) {
										processErrorFunc(pkg, call, node.Lhs[i].Pos(), node)
									}
								} else if ta, ok := rhs.(*ast.TypeAssertExpr); ok && asserts {
									if isBlank(node.Lhs[i]) {
										processTypeAssertFunc(pkg, ta, node.Lhs[i].Pos(), node)
									}
								}
							}
						} else if len(node.Rhs) == 1 {
							if call, ok := node.Rhs[0].(*ast.CallExpr); ok && returnsError(pkg, call) {
								if isBlank(node.Lhs[len(node.Lhs)-1]) {
									processErrorFunc(pkg, call, node.Lhs[len(node.Lhs)-1].Pos(), node)
								}
							} else if ta, ok := node.Rhs[0].(*ast.TypeAssertExpr); ok && asserts {
								if len(node.Lhs) == 2 && isBlank(node.Lhs[1]) {
									processTypeAssertFunc(pkg, ta, node.Lhs[1].Pos(), node)
								}
							}
						}
					}
					if asserts {
						if len(node.Rhs) == 1 && len(node.Lhs) == 1 {
							if ta, ok := node.Rhs[0].(*ast.TypeAssertExpr); ok {
								processTypeAssertFunc(pkg, ta, ta.Pos(), node)
							}
						}
					}
				case *ast.ValueSpec:
					if blank {
						if len(node.Values) == 1 {
							if call, ok := node.Values[0].(*ast.CallExpr); ok && returnsError(pkg, call) {
								if len(node.Names) > 0 && isBlank(node.Names[len(node.Names)-1]) {
									processErrorFunc(pkg, call, node.Names[len(node.Names)-1].Pos(), node)
								}
							}
						} else if len(node.Values) > 1 {
							for i, v := range node.Values {
								if call, ok := v.(*ast.CallExpr); ok && returnsError(pkg, call) {
									if i < len(node.Names) && isBlank(node.Names[i]) {
										processErrorFunc(pkg, call, node.Names[i].Pos(), node)
									}
								}
							}
						}
					}
				}
				return true
			})
		}
	}

	if len(errorsFound) > 0 {
		for _, err := range errorsFound {
			if verbose && err.FuncName != "" {
				fmt.Printf("%s:%d:%d:\t%s\t%s\n", err.Pos.Filename, err.Pos.Line, err.Pos.Column, err.FuncName, err.Line)
			} else {
				fmt.Printf("%s:%d:%d:\t%s\n", err.Pos.Filename, err.Pos.Line, err.Pos.Column, err.Line)
			}
		}
		os.Exit(1)
	}
}
EOF
./compile.sh
"}

{"command":"cat <<'EOF' > main.go
package main

import (
	"bytes"
	"encoding/json"
	"flag"
	"fmt"
	"go/ast"
	"go/importer"
	"go/parser"
	"go/printer"
	"go/token"
	"go/types"
	"io/ioutil"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
)

var defaultExcludes = []string{
	"(*bytes.Buffer).Write",
	"(*bytes.Buffer).WriteByte",
	"(*bytes.Buffer).WriteRune",
	"(*bytes.Buffer).WriteString",
	"(*strings.Builder).Write",
	"(*strings.Builder).WriteByte",
	"(*strings.Builder).WriteRune",
	"(*strings.Builder).WriteString",
	"fmt.Print",
	"fmt.Printf",
	"fmt.Println",
	"fmt.Fprint(os.Stderr)",
	"fmt.Fprintf(os.Stderr)",
	"fmt.Fprintln(os.Stderr)",
	"math/rand.Read",
	"(*math/rand.Rand).Read",
	"hash.Hash.Write",
	"hash.Hash32.Write",
	"hash.Hash64.Write",
}

type ExcludeRule struct {
	Name string
	Type string
}

type UncheckedError struct {
	Pos      token.Position
	Line     string
	FuncName string
}

func normalize(s string) string {
	s = strings.ReplaceAll(s, "(", "")
	s = strings.ReplaceAll(s, ")", "")
	s = strings.ReplaceAll(s, "*", "")
	return s
}

func isError(t types.Type) bool {
	if t == nil {
		return false
	}
	return t.String() == "error"
}

func returnsError(info *types.Info, call *ast.CallExpr) bool {
	t := info.Types[call].Type
	if t == nil {
		return false
	}
	if tuple, ok := t.(*types.Tuple); ok {
		if tuple.Len() > 0 {
			return isError(tuple.At(tuple.Len() - 1).Type())
		}
	} else {
		return isError(t)
	}
	return false
}

func isBlank(expr ast.Expr) bool {
	id, ok := expr.(*ast.Ident)
	return ok && id.Name == "_"
}

func getFuncName(info *types.Info, call *ast.CallExpr) string {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return ""
	}
	obj := info.Uses[sel.Sel]
	if obj == nil {
		return ""
	}
	fn, ok := obj.(*types.Func)
	if !ok {
		return ""
	}
	sig, _ := fn.Type().(*types.Signature)
	if recv := sig.Recv(); recv != nil {
		typ := recv.Type()
		if ptr, ok := typ.(*types.Pointer); ok {
			if named, ok := ptr.Elem().(*types.Named); ok {
				return "(*" + named.Obj().Pkg().Path() + "." + named.Obj().Name() + ")." + fn.Name()
			}
		}
		if named, ok := typ.(*types.Named); ok {
			return "(" + named.Obj().Pkg().Path() + "." + named.Obj().Name() + ")." + fn.Name()
		}
		return ""
	}
	if fn.Pkg() != nil {
		return fn.Pkg().Path() + "." + fn.Name()
	}
	return fn.Name()
}

func getFirstArgType(info *types.Info, call *ast.CallExpr) string {
	if len(call.Args) == 0 {
		return ""
	}
	arg := call.Args[0]
	if sel, ok := arg.(*ast.SelectorExpr); ok {
		if obj := info.Uses[sel.Sel]; obj != nil && obj.Pkg() != nil && obj.Pkg().Path() == "os" {
			if obj.Name() == "Stdout" || obj.Name() == "Stderr" {
				return "os." + obj.Name()
			}
		}
	}
	t := info.Types[arg].Type
	if t == nil {
		return ""
	}
	return types.TypeString(t, func(p *types.Package) string {
		// we don't know current pkg here easily, but we strip all pkg names by always returning name
		return p.Name()
	})
}

type stringFlags []string

func (f *stringFlags) String() string {
	return strings.Join(*f, ",")
}

func (f *stringFlags) Set(value string) error {
	*f = append(*f, value)
	return nil
}

type Package struct {
	Dir         string
	ImportPath  string
	Name        string
	GoFiles     []string
	TestGoFiles []string
	Imports     []string
	Deps        []string
	Error       *struct{ Err string }
}

type ParsedPkg struct {
	Pkg    *Package
	Types  *types.Package
	Info   *types.Info
	Syntax []*ast.File
}

type sourceImporter struct {
	fset       *token.FileSet
	packages   map[string]*ParsedPkg
	fallback   types.Importer
	listData   map[string]*Package
	inProgress map[string]bool
}

func (si *sourceImporter) Import(path string) (*types.Package, error) {
	if p, ok := si.packages[path]; ok {
		return p.Types, nil
	}
	p, err := si.fallback.Import(path)
	if err == nil {
		return p, nil
	}
	pkgData, ok := si.listData[path]
	if !ok {
		return nil, fmt.Errorf("not found: %s", path)
	}
	if si.inProgress[path] {
		return nil, fmt.Errorf("import cycle: %s", path)
	}
	si.inProgress[path] = true
	defer func() { si.inProgress[path] = false }()

	var files []*ast.File
	for _, file := range pkgData.GoFiles {
		fpath := filepath.Join(pkgData.Dir, file)
		f, err := parser.ParseFile(si.fset, fpath, nil, parser.ParseComments)
		if err == nil {
			files = append(files, f)
		}
	}

	info := &types.Info{
		Types:      make(map[ast.Expr]types.TypeAndValue),
		Defs:       make(map[*ast.Ident]types.Object),
		Uses:       make(map[*ast.Ident]types.Object),
		Implicits:  make(map[ast.Node]types.Object),
		Selections: make(map[*ast.SelectorExpr]*types.Selection),
		Scopes:     make(map[ast.Node]*types.Scope),
	}

	conf := types.Config{
		Importer: si,
		Error:    func(err error) {},
	}

	pkgType, _ := conf.Check(pkgData.ImportPath, si.fset, files, info)
	if pkgType == nil {
		pkgType = types.NewPackage(pkgData.ImportPath, pkgData.Name)
	}

	si.packages[path] = &ParsedPkg{
		Pkg:    pkgData,
		Types:  pkgType,
		Info:   info,
		Syntax: files,
	}

	return pkgType, nil
}

func main() {
	var abspath, asserts, blank, excludeonly, ignoretests, ignoregenerated, verbose bool
	var excludeFile, ignore, ignorepkg, mod string
	var tags stringFlags

	flag.BoolVar(&abspath, "abspath", false, "print absolute paths to files")
	flag.BoolVar(&asserts, "asserts", false, "if true, check for ignored type assertion results")
	flag.BoolVar(&blank, "blank", false, "if true, check for errors assigned to blank identifier")
	flag.StringVar(&excludeFile, "exclude", "", "Path to a file containing a list of functions to exclude from checking")
	flag.BoolVar(&excludeonly, "excludeonly", false, "Use only excludes from -exclude file")
	flag.StringVar(&ignore, "ignore", "", "[deprecated] comma-separated list of pairs of the form pkg:regex\n            the regex is used to ignore names within pkg.")
	flag.BoolVar(&ignoregenerated, "ignoregenerated", false, "if true, checking of files with generated code is disabled")
	flag.StringVar(&ignorepkg, "ignorepkg", "", "comma-separated list of package paths to ignore")
	flag.BoolVar(&ignoretests, "ignoretests", false, "if true, checking of _test.go files is disabled")
	flag.StringVar(&mod, "mod", "", "module download mode to use: readonly or vendor. See 'go help modules' for more.")
